Lemma cuts_ok : forall i T k, nth_error CUTS i = Some (T, k) ->
  exists sh, gplan_ok k = true /\ holes_only sh = true /\
    check ASEGS IT AASAN (ce_nxf ce) LIMIT ISP0 (XN IT NXF) XE0 XB (HScut ce CUTS (Datatypes.S i)) 0%nat BFUEL FUEL None T k = COk sh.
Proof.
  intros i T k H.
  assert (X : cut_stmt i).
  {
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM0.GaWF_A0.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM0.GaWF_A1.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM0.GaWF_A2.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM0.GaWF_A3.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM0.GaWF_A4.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM0.GaWF_A5.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM0.GaWF_A6.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM0.GaWF_A7.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM1.GaWF_A8.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM1.GaWF_A9.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM1.GaWF_A10.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM1.GaWF_A11.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM1.GaWF_A12.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM1.GaWF_A13.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM1.GaWF_A14.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM1.GaWF_A15.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM2.GaWF_A16.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM2.GaWF_A17.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM2.GaWF_A18.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM2.GaWF_A19.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM2.GaWF_A20.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM2.GaWF_A21.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM2.GaWF_A22.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM2.GaWF_A23.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM3.GaWF_A24.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM3.GaWF_A25.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM3.GaWF_A26.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM3.GaWF_A27.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM3.GaWF_A28.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM3.GaWF_A29.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM3.GaWF_A30.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM3.GaWF_A31.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM4.GaWF_A32.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM4.GaWF_A33.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM4.GaWF_A34.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM4.GaWF_A35.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM4.GaWF_A36.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM4.GaWF_A37.cut|].
  destruct i as [|i]; [apply cut_ok_sound; exact GaWFcM4.GaWF_A38.cut|].
  exfalso. rewrite (proj2 (nth_error_None CUTS _)) in H; [discriminate|]. rewrite CUTS_len. unfold NCUTS. lia. }
  unfold cut_stmt in X. rewrite H in X. exact X.
Qed.
Lemma top_cert : exists sh, holes_only sh = true /\
  check ASEGS IT AASAN (ce_nxf ce) LIMIT ISP0 (XN IT NXF) XE0 XB (HScut ce CUTS 0) 0%nat BFUEL FUEL None (ce_tin ce) plan_top = COk sh.
Proof. eexists. split; [| exact GaWF.top]. reflexivity. Qed.

Section Contract.
Context {RC : run_ceil}.
Variable RZ : GPS.rz_t.
Hypothesis RZ_silent1 : GPS.RZ_SILENT1 ASEGS RZ.
Hypothesis RZ_exit : GPS.RZ_EXIT ASEGS RZ.
Hypothesis RZ_conseq : GPS.RZ_CONSEQ RZ.
Variable SHC : list (Z * Z).
Variable KCAP : Z.
Variable AINVH : list (Z * Z) -> list (Z * Z) -> Z -> Z -> Z -> (word -> option byte) -> Model -> Prop.
Hypothesis HP : hprops [] GASAN SHC AINVH.
Hypothesis GC_all : forall PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV,
  itab_sound ASEGS IT -> 0 <= B0 -> 0 <= C0 -> B0 + 0 <= GBUDGET -> C0 + 0 <= GCOUNT -> Z.of_nat (length HIDF) + FTOPf <= FMIN ->
  (forall E E', env_agree NXF E E' -> UINV E -> UINV E') ->
  gcontracts ASEGS IT AASAN NXF PERMf TOPf FS0 SHC (VSHf HID HIDF) (AINV_f [] GASAN AINVH PERMf TOPf HID HIDF M0 B0 C0) KCAP FTOPf fx_ok UINV RZ GASAN 0 0.

Theorem write_float_asan_callee : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH ce.
Proof.
  destruct top_cert as (sh & Hsh & CERT).
  refine (contract_of_cert_xb_cut ASEGS AASAN asan_in_hull asan_hull_ok [] GASAN fx_ok (RUN_sound_fx ASEGS) RZ RZ_silent1 RZ_exit RZ_conseq
            SHC KCAP AINVH HP asan_G_ro_img2 asan_G_img_al asan_G_img_shlo asan_A_img_hi asan_A_img_lo asan_segs_wx
            ce IT IT_ok LIMIT 0%nat BFUEL FUEL (XN IT NXF) _ XB _ CUTS cuts_ok plan_top sh top_gplan Hsh CERT).
  -   intros PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa.
    apply (XN_sound IT IT_ok NXF RZ RZ_silent1 SHC KCAP AINVH HP PERMf TOPf FS0 HID HIDF M0 B0 C0 HB0 HC0 HBc HCc FTOPf HFB UINV HUa).
    (apply GC_all; first [assumption | exact IT_ok]).
  - intros PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa.
    intros id args cs csa csb E1 fx1 R1 M1 m1 T1 HC1 Hn. discriminate Hn.
Qed.
End Contract.
End GaWFC.
