Lemma xL1 : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (GaAA.ceL1 cfg).
Proof.
  refine (callee_gen_cut (GaAA.ceL1 cfg) (XCUTS cfg INVm JS1m elem) (XPLAN_L1 cfg) _ eq_refl eq_refl eq_refl gplan_XL1 hs1 _ cert_L1X).
  intros i T k H. destruct i as [|i]; [|destruct i; discriminate H]. injection H as <- <-.
  exists (SHole 1). split; [exact gplan_XC|]. split; [reflexivity|]. exact cert_CX.
Qed.

Theorem write_aligned_array_f32_asan_callee_S : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (GaAA.ce cfg MS).
Proof.
  refine (callee_gen_cutsh (GaAA.ce cfg MS) (XCUTS cfg INVm JS1m elem) (XPLAN_S cfg INVm JS1m elem) _ eq_refl eq_refl eq_refl gplan_XS hs0 _ cert_SX).
  intros i T k H. destruct i as [|i]; [|destruct i; discriminate H]. injection H as <- <-.
  exists (SHole 1). split; [exact gplan_XC|]. split; [reflexivity|].
  exists (HScut (GaAA.ceL1 cfg) (XCUTS cfg INVm JS1m elem) 1). split; [exact (xhs_sub cfg (XCUTS cfg INVm JS1m elem) eq_refl) | exact cert_CX].
Qed.
Theorem write_aligned_array_f32_asan_callee_L1 : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (GaAA.ceL1 cfg).
Proof. exact xL1. Qed.
End Contract.
