Hypothesis GC_all : forall PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV,
  itab_sound ASEGS IT -> 0 <= B0 -> 0 <= C0 -> B0 + 0 <= GBUDGET -> C0 + 0 <= GCOUNT -> Z.of_nat (length HIDF) + FTOPf <= FMIN ->
