Lemma hs0 : holes_only (SHole 0) = true. Proof. reflexivity. Qed.
Lemma hs2 : holes_only (SHole 2) = true. Proof. reflexivity. Qed.

Section Contract.
Context {RC : run_ceil}.
Variable RZ : GPS.rz_t.
Hypothesis RZ_silent1 : GPS.RZ_SILENT1 ASEGS RZ.
Hypothesis RZ_exit : GPS.RZ_EXIT ASEGS RZ.
Hypothesis RZ_conseq : GPS.RZ_CONSEQ RZ.
Variable SHC : list (Z * Z).
Variable KCAP : Z.
Variable AINVH : list (Z * Z) -> list (Z * Z) -> Z -> Z -> Z -> (word -> option byte) -> Model -> Prop.
Hypothesis HP : hprops [] GASAN SHC AINVH.
Hypothesis GC_all : forall IT NXF bc cc PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV,
  itab_sound ASEGS IT -> 0 <= B0 -> 0 <= C0 -> B0 + bc <= GBUDGET -> C0 + cc <= GCOUNT -> Z.of_nat (length HIDF) + FTOPf <= FMIN ->
  (forall E E', env_agree NXF E E' -> UINV E -> UINV E') ->
  gcontracts ASEGS IT AASAN NXF PERMf TOPf FS0 SHC (VSHf HID HIDF) (AINV_f [] GASAN AINVH PERMf TOPf HID HIDF M0 B0 C0) KCAP FTOPf fx_ok UINV RZ GASAN bc cc.

(* [comment removed for export] *)
Lemma esc_callee_cut : forall (c : gcallee) (p : plan) sh,
  ce_nxf c = GaEsc.NXF -> ce_bcap c = GaEsc.BCAP -> ce_ccap c = GaEsc.CCAP -> gplan_ok p = true -> holes_only sh = true ->
  (forall i T k, nth_error GaEsc.CUTS_E i = Some (T, k) -> exists sh, gplan_ok k = true /\ holes_only sh = true /\
     (check ASEGS GaEsc.IT AASAN (ce_nxf c) LIMIT ISP0 GaEsc.XN XE0 GaEsc.XB (HScut c GaEsc.CUTS_E (Datatypes.S i)) 0%nat BFUEL GaEsc.FUEL None T k = COk sh \/
      exists HS', hs_sub HS' (HScut c GaEsc.CUTS_E (Datatypes.S i)) /\
        check ASEGS GaEsc.IT AASAN (ce_nxf c) LIMIT ISP0 GaEsc.XN XE0 GaEsc.XB HS' 0%nat BFUEL GaEsc.FUEL None T k = COk sh)) ->
  check ASEGS GaEsc.IT AASAN (ce_nxf c) LIMIT ISP0 GaEsc.XN XE0 GaEsc.XB (HScut c GaEsc.CUTS_E 0) 0%nat BFUEL GaEsc.FUEL None (ce_tin c) p = COk sh ->
  callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH c.
Proof.
  intros c p sh HN HB HC HG HSH HCUTS CERT. unfold callee_contract.
  refine (contract_of_cert_when_cutX ASEGS AASAN asan_in_hull asan_hull_ok [] GASAN fx_ok (RUN_sound_fx ASEGS) RZ RZ_silent1 RZ_exit RZ_conseq
            SHC KCAP AINVH HP asan_G_ro_img2 asan_G_img_al asan_G_img_shlo asan_A_img_hi asan_A_img_lo asan_segs_wx
            c GaEsc.IT GaEsc.IT_ok LIMIT 0%nat BFUEL GaEsc.FUEL GaEsc.XN QTRUE _ _ GaEsc.XB _ GaEsc.XN _ GaEsc.XB _ GaEsc.CUTS_E HCUTS p sh HG HSH CERT).
  - intros E E' _ _. exact I.
  - intros PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa HUQ. unfold GaEsc.XN. rewrite HN in *. rewrite HB in HBc. rewrite HC in HCc.
    apply GaNumT.GaPw.XNw_sound.
    refine (XNc_sound ASEGS GaEsc.IT AASAN asan_in_hull asan_hull_ok GaEsc.IT_ok GaEsc.NXF [] GASAN GaEsc.BCAP GaEsc.CCAP fx_ok SHC KCAP AINVH HP
              asan_G_ro_img2 asan_G_img_al asan_G_img_shlo nil_SWIN_img asan_segs_out asan_A_img_hi asan_A_img_lo asan_segs_wx
              PERMf TOPf FS0 HID HIDF M0 B0 C0 HB0 HC0 HBc HCc FTOPf HFB UINV HUa RZ RZ_silent1 CT0 _ _).
    + intros id ce' H. discriminate H.
    + (apply GC_all; first [assumption | exact GaEsc.IT_ok]).
  - intros PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa HUQ. unfold GaEsc.XB. rewrite HN in *. rewrite HB in HBc. rewrite HC in HCc.
    refine (XBc_sound0 ASEGS AASAN asan_in_hull asan_hull_ok GaEsc.NXF [] GASAN GaEsc.BCAP GaEsc.CCAP fx_ok SHC KCAP AINVH HP
              asan_G_ro_img2 asan_G_img_al asan_G_img_shlo nil_SWIN_img asan_segs_out asan_A_img_hi asan_A_img_lo asan_segs_wx
              PERMf TOPf FS0 HID HIDF M0 B0 C0 HB0 HC0 HBc HCc FTOPf HFB UINV HUa RZ RZ_silent1 CT2_resize _).
    intros id c' H. exact (CT2_resize_sound RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all id c' H).
  - intros PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa HUQ. unfold GaEsc.XN. rewrite HN in *. rewrite HB in HBc. rewrite HC in HCc.
    apply GaNumT.GaPw.XNw_sound.
    refine (XNc_sound ASEGS GaEsc.IT AASAN asan_in_hull asan_hull_ok GaEsc.IT_ok GaEsc.NXF [] GASAN GaEsc.BCAP GaEsc.CCAP fx_ok SHC KCAP AINVH HP
              asan_G_ro_img2 asan_G_img_al asan_G_img_shlo nil_SWIN_img asan_segs_out asan_A_img_hi asan_A_img_lo asan_segs_wx
              PERMf TOPf FS0 HID HIDF M0 B0 C0 HB0 HC0 HBc HCc FTOPf HFB UINV HUa RZ RZ_silent1 CT0 _ _).
    + intros id ce' H. discriminate H.
    + (apply GC_all; first [assumption | exact GaEsc.IT_ok]).
  - intros PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa HUQ. unfold GaEsc.XB. rewrite HN in *. rewrite HB in HBc. rewrite HC in HCc.
    refine (XBc_sound0 ASEGS AASAN asan_in_hull asan_hull_ok GaEsc.NXF [] GASAN GaEsc.BCAP GaEsc.CCAP fx_ok SHC KCAP AINVH HP
              asan_G_ro_img2 asan_G_img_al asan_G_img_shlo nil_SWIN_img asan_segs_out asan_A_img_hi asan_A_img_lo asan_segs_wx
              PERMf TOPf FS0 HID HIDF M0 B0 C0 HB0 HC0 HBc HCc FTOPf HFB UINV HUa RZ RZ_silent1 CT2_resize _).
    intros id c' H. exact (CT2_resize_sound RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all id c' H).
Qed.
Lemma esc_hs_L : hs_sub (HScut GaEsc.ceL1 GaEsc.CUTS_E 1) (HScut (GaEsc.ce MS) GaEsc.CUTS_E 1).
Proof.
  intros h ch Hh. left. exists 1%nat. unfold HScut, NT in Hh |- *.
  change (ce_touts GaEsc.ceL1) with [GaEsc.tout ML ML; GaEsc.tout ML ML] in Hh. change (ce_touts (GaEsc.ce MS)) with [GaEsc.tout MS MS; GaEsc.tout MS ML].
  change (length [GaEsc.tout ML ML; GaEsc.tout ML ML]) with 2%nat in Hh. change (length [GaEsc.tout MS MS; GaEsc.tout MS ML]) with 2%nat.
  cbn [Nat.ltb Nat.leb nth_error]. rewrite GaEsc.tout_L.
  destruct h as [|[|h]]; cbn [Nat.ltb Nat.leb nth_error] in Hh; [exact Hh | exact Hh |].
  destruct h as [|h]; cbn [Nat.sub Nat.leb] in Hh; [discriminate Hh|].
  unfold GaEsc.CUTS_E in Hh. cbn [nth_error] in Hh. destruct h; discriminate Hh.
Qed.


Theorem esc_asan_callee_S : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (GaEsc.ce MS).
Proof.
  refine (esc_callee_cut (GaEsc.ce MS) (GaEsc.planX MS) _ eq_refl eq_refl eq_refl (esc_gplanX MS) hs0 _ esc_cert_S).
  intros i T k Hn. destruct i as [|i]; [|destruct i; discriminate Hn].
  injection Hn as <- <-. exists (SHole 0). split; [exact GaEsc.esc_gplanC|]. split; [reflexivity|].
  right. exists (HScut GaEsc.ceL1 GaEsc.CUTS_E 1). split; [exact esc_hs_L | exact esc_cut_L].
Qed.

Theorem esc_asan_callee_L1 : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH GaEsc.ceL1.
Proof. (refine (esc_callee_cut GaEsc.ceL1 (GaEsc.planX ML) _ eq_refl eq_refl eq_refl (esc_gplanX ML) hs2 _ esc_cert_L1);
  intros i T k Hn; destruct i as [|i]; [|destruct i; discriminate Hn];
  injection Hn as <- <-; exists (SHole 0); split; [exact GaEsc.esc_gplanC|]; split; [reflexivity|]; left; exact esc_cut_L). Qed.
End Contract.
End GaEscC.
