Lemma w16_callee_gen : forall (c : gcallee) (B : Z) (p : plan) sh,
  ce_nxf c = NXF -> ce_bcap c = BCAP -> ce_ccap c = CCAP -> gplan_ok p = true -> holes_only sh = true ->
  check ASEGS (IT B) AASAN (ce_nxf c) LIMIT ISP0 (XN B) XE0 XB (HSce c) 0%nat BFUEL FUEL16 None (ce_tin c) p = COk sh ->
  callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH c.
Proof.
  intros c B p sh HN HB HC HG HSH CERT.
  refine (contract_of_cert_xb ASEGS AASAN asan_in_hull asan_hull_ok [] GASAN fx_ok (RUN_sound_fx ASEGS) RZ RZ_silent1 RZ_exit RZ_conseq
            SHC KCAP AINVH HP asan_G_ro_img2 asan_G_img_al asan_G_img_shlo asan_A_img_hi asan_A_img_lo asan_segs_wx
            c (IT B) (IT_ok B) LIMIT 0%nat BFUEL FUEL16 (XN B) _ XB _ p _ HG HSH CERT).
  - intros PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa. unfold XN. rewrite HN in *. rewrite HB in HBc. rewrite HC in HCc.
    apply XNw_sound.
    refine (XNc_sound ASEGS (IT B) AASAN asan_in_hull asan_hull_ok (IT_ok B) NXF [] GASAN BCAP CCAP fx_ok SHC KCAP AINVH HP
              asan_G_ro_img2 asan_G_img_al asan_G_img_shlo nil_SWIN_img asan_segs_out asan_A_img_hi asan_A_img_lo asan_segs_wx
              PERMf TOPf FS0 HID HIDF M0 B0 C0 HB0 HC0 HBc HCc FTOPf HFB UINV HUa RZ RZ_silent1 CT0 _ _).
    + intros id ce' H. discriminate H.
    + (apply GC_all; first [assumption | exact (IT_ok B)]).
  - intros PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa. unfold XB. rewrite HN in *. rewrite HB in HBc. rewrite HC in HCc.
    refine (XBc_sound0 ASEGS AASAN asan_in_hull asan_hull_ok NXF [] GASAN BCAP CCAP fx_ok SHC KCAP AINVH HP
              asan_G_ro_img2 asan_G_img_al asan_G_img_shlo nil_SWIN_img asan_segs_out asan_A_img_hi asan_A_img_lo asan_segs_wx
              PERMf TOPf FS0 HID HIDF M0 B0 C0 HB0 HC0 HBc HCc FTOPf HFB UINV HUa RZ RZ_silent1 CT2_resize _).
    intros id c' H. exact (CT2_resize_sound RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all id c' H).
Qed.

Theorem write_u16_u8tag_asan_callee_L : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (ce ML B16U).
Proof. apply callee_contract_L_of_L1_az. exact (w16_callee_gen (ceL1 B16U) B16U (PLAN B16U ML) _ eq_refl eq_refl eq_refl (w16_gplan B16U ML) hs1 w16u_cert_L1). Qed.
Theorem write_u16_u8tag_asan_callee_S : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (ce MS B16U).
Proof. exact (w16_callee_gen (ce MS B16U) B16U (PLAN B16U MS) _ eq_refl eq_refl eq_refl (w16_gplan B16U MS) hs0 w16u_cert_S). Qed.
Theorem write_u16_inttag_asan_callee_L : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (ce ML B16I).
Proof. apply callee_contract_L_of_L1_az. exact (w16_callee_gen (ceL1 B16I) B16I (PLAN B16I ML) _ eq_refl eq_refl eq_refl (w16_gplan B16I ML) hs1 w16i_cert_L1). Qed.
Theorem write_u16_inttag_asan_callee_S : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (ce MS B16I).
Proof. exact (w16_callee_gen (ce MS B16I) B16I (PLAN B16I MS) _ eq_refl eq_refl eq_refl (w16_gplan B16I MS) hs0 w16i_cert_S). Qed.
Theorem write_u16_u8tag_asan_callee_L1 : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (ceL1 B16U).
Proof. exact (w16_callee_gen (ceL1 B16U) B16U (PLAN B16U ML) _ eq_refl eq_refl eq_refl (w16_gplan B16U ML) hs1 w16u_cert_L1). Qed.
Theorem write_u16_inttag_asan_callee_L1 : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (ceL1 B16I).
Proof. exact (w16_callee_gen (ceL1 B16I) B16I (PLAN B16I ML) _ eq_refl eq_refl eq_refl (w16_gplan B16I ML) hs1 w16i_cert_L1). Qed.
End Contract.
End GaW16C.
