Lemma cuts_ok_US : forall i T k, nth_error (CUTS BNU MS (GaNumT.ce MS BNU) (GaNum.XN BNU) (arm_of BNU)) i = Some (T, k) ->
  exists sh, gplan_ok k = true /\ holes_only sh = true /\
    check ASEGS (IT BNU) AASAN (ce_nxf (GaNumT.ce MS BNU)) LIMIT ISP0 (GaNum.XN BNU) XE0 (XB BNU) (HScut (GaNumT.ce MS BNU) (CUTS BNU MS (GaNumT.ce MS BNU) (GaNum.XN BNU) (arm_of BNU)) (Datatypes.S i)) 0%nat BFUEL FUELN None T k = COk sh.
Proof.
  intros i T k H.
  assert (X : cut_stmt BNU MS (GaNumT.ce MS BNU) (GaNum.XN BNU) (arm_of BNU) i).
  { destruct i as [|i]; [apply cut_ok_sound; exact GaNumcM0.GaNumCertUS_A0.cut|].
    destruct i as [|i]; [apply cut_ok_sound; exact GaNumcM0.GaNumCertUS_A1.cut|].
    destruct i as [|i]; [apply cut_ok_sound; exact GaNumcM0.GaNumCertUS_A2.cut|].
    destruct i as [|i]; [apply cut_ok_sound; exact GaNumcM0.GaNumCertUS_A3.cut|].
    destruct i as [|i]; [apply cut_ok_sound; exact GaNumcM0.GaNumCertUS_A4.cut|].
    exfalso. rewrite (proj2 (nth_error_None (CUTS BNU MS (GaNumT.ce MS BNU) (GaNum.XN BNU) (arm_of BNU)) _)) in H; [discriminate|]. rewrite CUTS_len. unfold NCUTS. lia. }
  unfold cut_stmt in X. rewrite H in X. exact X.
Qed.
