Section Contract.
Context {RC : run_ceil}.
Variable RZ : GPS.rz_t.
Hypothesis RZ_silent1 : GPS.RZ_SILENT1 ASEGS RZ.
Hypothesis RZ_exit : GPS.RZ_EXIT ASEGS RZ.
Hypothesis RZ_conseq : GPS.RZ_CONSEQ RZ.
Variable SHC : list (Z * Z).
Variable KCAP : Z.
Variable AINVH : list (Z * Z) -> list (Z * Z) -> Z -> Z -> Z -> (word -> option byte) -> Model -> Prop.
Hypothesis HP : hprops [] GASAN SHC AINVH.
Hypothesis GC_all : forall IT NXF bc cc PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV,
  itab_sound ASEGS IT -> 0 <= B0 -> 0 <= C0 -> B0 + bc <= GBUDGET -> C0 + cc <= GCOUNT -> Z.of_nat (length HIDF) + FTOPf <= FMIN ->
  (forall E E', env_agree NXF E E' -> UINV E -> UINV E') ->
  gcontracts ASEGS IT AASAN NXF PERMf TOPf FS0 SHC (VSHf HID HIDF) (AINV_f [] GASAN AINVH PERMf TOPf HID HIDF M0 B0 C0) KCAP FTOPf fx_ok UINV RZ GASAN bc cc.

Lemma CT_ok : forall id ce', GaNum.CT id = Some ce' -> callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH ce'.
Proof.
  intros id ce' H. unfold GaNum.CT in H.
  destruct (Nat.eqb id 130). { injection H as <-. exact (GaTc32C.to_chars_u32_asan_callee RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP (GC_all _ _ 0 0)). }
  destruct (Nat.eqb id 132). { injection H as <-. exact (GaI32C.to_chars40kb_i32_asan_callee RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP (GC_all _ _ 0 0)). }
  destruct (Nat.eqb id 133). { injection H as <-. exact (GaU32C.to_chars40kb_u32_asan_callee RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP (GC_all _ _ 0 0)). }
  destruct (Nat.eqb id 134). { injection H as <-. exact (GaI64C.to_chars40kb_i64_asan_callee RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP (GC_all _ _ 0 0)). }
  destruct (Nat.eqb id 135). { injection H as <-. exact (GaU64C.to_chars40kb_u64_asan_callee RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP (GC_all _ _ 0 0)). }
  destruct (Nat.eqb id 136). { injection H as <-. exact (GaWFC.write_float_asan_callee RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP (GC_all _ _ 0 0)). }
  destruct (Nat.eqb id 137). { injection H as <-. exact (GaWDC.write_double_asan_callee RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP (GC_all _ _ 0 0)). }
  destruct (Nat.eqb id 142). { injection H as <-. exact (GaI32C.to_chars40kb_i32_asan_callee_S RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP (GC_all _ _ 0 0)). }
  destruct (Nat.eqb id 143); [|discriminate H]. injection H as <-. exact (GaU32C.to_chars40kb_u32_asan_callee_S RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP (GC_all _ _ 0 0)).
Qed.

Lemma W16_L : forall B, callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (GaW16.ce ML (B16 B)).
Proof. intros B. unfold B16. destruct (is_int B); [exact (GaW16C.write_u16_inttag_asan_callee_L RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all) | exact (GaW16C.write_u16_u8tag_asan_callee_L RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)]. Qed.
Lemma W16_S : forall B, callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (GaW16.ce MS (B16 B)).
Proof. intros B. unfold B16. destruct (is_int B); [exact (GaW16C.write_u16_inttag_asan_callee_S RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all) | exact (GaW16C.write_u16_u8tag_asan_callee_S RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)]. Qed.
Lemma W16_L1 : forall B, callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (GaW16.ceL1 (B16 B)).
Proof. intros B. unfold B16. destruct (is_int B); [exact (GaW16C.write_u16_inttag_asan_callee_L1 RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all) | exact (GaW16C.write_u16_u8tag_asan_callee_L1 RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)]. Qed.

Lemma CT1_ok : forall B id ce', GaNum.CT1 B id = Some ce' -> callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH ce'.
Proof.
  intros B id ce' H. unfold GaNum.CT1 in H.
  destruct (Nat.eqb id 148); [|exact (CT_ok id ce' H)]. injection H as <-. exact (W16_L1 B).
Qed.
Lemma CT2w_ok : forall B id c, GaNum.CT2w B id = Some c -> callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (c2_merged c).
Proof.
  intros B id c H. unfold GaNum.CT2w in H.
  destruct (Nat.eqb id 138). { injection H as <-. change (callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (GaW16.ce ML (B16 B))). exact (W16_L B). }
  destruct (Nat.eqb id 139); [|discriminate H].
  injection H as <-. change (callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (GaW16.ce MS (B16 B))). exact (W16_S B).
Qed.
Lemma CT2_ok : forall B id c, GaNum.CT2 B id = Some c -> callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (c2_merged c).
Proof.
  intros B. unfold GaNum.CT2.
  apply (ct2_or_sound (fun c => callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (c2_merged c))).
  - exact (CT2w_ok B).
  - intros id c H. exact (CT2_resize_sound RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all id c H).
Qed.
