Lemma XN_ok : forall B PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 (UINV : env -> Prop),
  0 <= B0 -> 0 <= C0 -> B0 + BCAP <= GBUDGET -> C0 + CCAP <= GCOUNT -> Z.of_nat (length HIDF) + FTOPf <= FMIN ->
  (forall E E', env_agree NXF E E' -> UINV E -> UINV E') ->
  GPS.ext_stmt ASEGS NXF (GaNum.XN B) PERMf TOPf FS0 SHC (VSHf HID HIDF) (AINV_f [] GASAN AINVH PERMf TOPf HID HIDF M0 B0 C0) KCAP FTOPf fx_ok UINV RZ.
Proof.
  intros B PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa. unfold GaNum.XN.
  apply GaNumT.GaPw.XNw_sound.
  refine (XNc_sound ASEGS (GaNumT.IT B) AASAN asan_in_hull asan_hull_ok (GaNumT.IT_ok B) GaNumT.NXF [] GASAN GaNumT.BCAP GaNumT.CCAP fx_ok SHC KCAP AINVH HP
            asan_G_ro_img2 asan_G_img_al asan_G_img_shlo nil_SWIN_img asan_segs_out asan_A_img_hi asan_A_img_lo asan_segs_wx
            PERMf TOPf FS0 HID HIDF M0 B0 C0 HB0 HC0 HBc HCc FTOPf HFB UINV HUa RZ RZ_silent1 GaNum.CT _ _).
  - intros id ce' H. exact (CT_ok id ce' H).
  - (apply GC_all; first [assumption | exact (GaNumT.IT_ok B)]).
Qed.
Lemma XN1_ok : forall B PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 (UINV : env -> Prop),
