Lemma XB_ok : forall B PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 (UINV : env -> Prop),
  0 <= B0 -> 0 <= C0 -> B0 + BCAP <= GBUDGET -> C0 + CCAP <= GCOUNT -> Z.of_nat (length HIDF) + FTOPf <= FMIN ->
  (forall E E', env_agree NXF E E' -> UINV E -> UINV E') ->
