            (GaNumT.ce MS BNU) (GaNumT.IT BNU) (GaNumT.IT_ok BNU) LIMIT 0%nat BFUEL FUELN (GaNum.XN BNU) _ (GaNum.XB BNU) _ (CUTS BNU MS (GaNumT.ce MS BNU) (GaNum.XN BNU) (arm_of BNU)) cuts_ok_US plan_top (SHole 2) top_gplan eq_refl GaNumCertUS.top).
