Lemma callee_gen_cut : forall (c : gcallee) (CUTS : list (acs * plan)) (p : plan) sh,
  ce_nxf c = GaWA.NXF -> ce_bcap c = BCAP -> ce_ccap c = CCAP -> gplan_ok p = true -> holes_only sh = true ->
  (forall i T k, nth_error CUTS i = Some (T, k) -> exists sh', gplan_ok k = true /\ holes_only sh' = true /\
     check ASEGS (GaWA.IT cfg) AASAN (ce_nxf c) LIMIT ISP0 XN XE0 GaWA.XB (HScut c CUTS (Datatypes.S i)) 0%nat BFUEL FUELA None T k = COk sh') ->
  check ASEGS (GaWA.IT cfg) AASAN (ce_nxf c) LIMIT ISP0 XN XE0 GaWA.XB (HScut c CUTS 0) 0%nat BFUEL FUELA None (ce_tin c) p = COk sh ->
  callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH c.
Proof.
  intros c CUTS p sh HN HB HC HG HSH HCUTS CERT.
  refine (contract_of_cert_xb_cut ASEGS AASAN asan_in_hull asan_hull_ok [] GASAN fx_ok (RUN_sound_fx ASEGS) RZ RZ_silent1 RZ_exit RZ_conseq
            SHC KCAP AINVH HP asan_G_ro_img2 asan_G_img_al asan_G_img_shlo asan_A_img_hi asan_A_img_lo asan_segs_wx
            c (GaWA.IT cfg) (GaWA.IT_ok cfg) LIMIT 0%nat BFUEL FUELA XN _ GaWA.XB _ CUTS HCUTS p _ HG HSH CERT).
  - intros PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa. unfold XN. rewrite HN in *. rewrite HB in HBc. rewrite HC in HCc.
    apply GaNumT.GaPw.XNw_sound.
    refine (XNc_sound ASEGS (GaWA.IT cfg) AASAN asan_in_hull asan_hull_ok (GaWA.IT_ok cfg) GaWA.NXF [] GASAN BCAP CCAP fx_ok SHC KCAP AINVH HP
              asan_G_ro_img2 asan_G_img_al asan_G_img_shlo nil_SWIN_img asan_segs_out asan_A_img_hi asan_A_img_lo asan_segs_wx
              PERMf TOPf FS0 HID HIDF M0 B0 C0 HB0 HC0 HBc HCc FTOPf HFB UINV HUa RZ RZ_silent1 CT _ _).
    + intros id ce' H. discriminate H.
    + (apply GC_all; first [assumption | exact (GaWA.IT_ok cfg)]).
  - intros PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa. unfold GaWA.XB. rewrite HN in *. rewrite HB in HBc. rewrite HC in HCc.
    refine (XBc_sound0 ASEGS AASAN asan_in_hull asan_hull_ok GaWA.NXF [] GASAN BCAP CCAP fx_ok SHC KCAP AINVH HP
              asan_G_ro_img2 asan_G_img_al asan_G_img_shlo nil_SWIN_img asan_segs_out asan_A_img_hi asan_A_img_lo asan_segs_wx
              PERMf TOPf FS0 HID HIDF M0 B0 C0 HB0 HC0 HBc HCc FTOPf HFB UINV HUa RZ RZ_silent1 CT2_resize _).
    intros id c' H. exact (CT2_resize_sound RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all id c' H).
Qed.
(* [comment removed for export] *)
Lemma callee_gen_cutsh : forall (c : gcallee) (CUTS : list (acs * plan)) (p : plan) sh,
  ce_nxf c = GaWA.NXF -> ce_bcap c = BCAP -> ce_ccap c = CCAP -> gplan_ok p = true -> holes_only sh = true ->
  (forall i T k, nth_error CUTS i = Some (T, k) -> exists sh', gplan_ok k = true /\ holes_only sh' = true /\
     exists HS', hs_sub HS' (HScut c CUTS (Datatypes.S i)) /\
       check ASEGS (GaWA.IT cfg) AASAN GaWA.NXF LIMIT ISP0 XN XE0 GaWA.XB HS' 0%nat BFUEL FUELA None T k = COk sh') ->
  check ASEGS (GaWA.IT cfg) AASAN (ce_nxf c) LIMIT ISP0 XN XE0 GaWA.XB (HScut c CUTS 0) 0%nat BFUEL FUELA None (ce_tin c) p = COk sh ->
  callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH c.
Proof.
  intros c CUTS p sh HN HB HC HG HSH HCUTS CERT. unfold callee_contract.
  refine (contract_of_cert_when_cutX ASEGS AASAN asan_in_hull asan_hull_ok [] GASAN fx_ok (RUN_sound_fx ASEGS) RZ RZ_silent1 RZ_exit RZ_conseq
            SHC KCAP AINVH HP asan_G_ro_img2 asan_G_img_al asan_G_img_shlo asan_A_img_hi asan_A_img_lo asan_segs_wx
            c (GaWA.IT cfg) (GaWA.IT_ok cfg) LIMIT 0%nat BFUEL FUELA XN QTRUE _ _ GaWA.XB _ XN _ GaWA.XB _ CUTS _ p sh HG HSH CERT).
  - intros E E' _ _. exact I.
  - intros PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa _. unfold XN. rewrite HN in *. rewrite HB in HBc. rewrite HC in HCc.
    apply GaNumT.GaPw.XNw_sound.
    refine (XNc_sound ASEGS (GaWA.IT cfg) AASAN asan_in_hull asan_hull_ok (GaWA.IT_ok cfg) GaWA.NXF [] GASAN BCAP CCAP fx_ok SHC KCAP AINVH HP
              asan_G_ro_img2 asan_G_img_al asan_G_img_shlo nil_SWIN_img asan_segs_out asan_A_img_hi asan_A_img_lo asan_segs_wx
              PERMf TOPf FS0 HID HIDF M0 B0 C0 HB0 HC0 HBc HCc FTOPf HFB UINV HUa RZ RZ_silent1 CT _ _).
    + intros id ce' H. discriminate H.
    + (apply GC_all; first [assumption | exact (GaWA.IT_ok cfg)]).
  - intros PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa _. unfold GaWA.XB. rewrite HN in *. rewrite HB in HBc. rewrite HC in HCc.
    refine (XBc_sound0 ASEGS AASAN asan_in_hull asan_hull_ok GaWA.NXF [] GASAN BCAP CCAP fx_ok SHC KCAP AINVH HP
              asan_G_ro_img2 asan_G_img_al asan_G_img_shlo nil_SWIN_img asan_segs_out asan_A_img_hi asan_A_img_lo asan_segs_wx
              PERMf TOPf FS0 HID HIDF M0 B0 C0 HB0 HC0 HBc HCc FTOPf HFB UINV HUa RZ RZ_silent1 CT2_resize _).
    intros id c' H. exact (CT2_resize_sound RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all id c' H).
  - intros PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa _. unfold XN. rewrite HN in *. rewrite HB in HBc. rewrite HC in HCc.
    apply GaNumT.GaPw.XNw_sound.
    refine (XNc_sound ASEGS (GaWA.IT cfg) AASAN asan_in_hull asan_hull_ok (GaWA.IT_ok cfg) GaWA.NXF [] GASAN BCAP CCAP fx_ok SHC KCAP AINVH HP
              asan_G_ro_img2 asan_G_img_al asan_G_img_shlo nil_SWIN_img asan_segs_out asan_A_img_hi asan_A_img_lo asan_segs_wx
              PERMf TOPf FS0 HID HIDF M0 B0 C0 HB0 HC0 HBc HCc FTOPf HFB UINV HUa RZ RZ_silent1 CT _ _).
    + intros id ce' H. discriminate H.
    + (apply GC_all; first [assumption | exact (GaWA.IT_ok cfg)]).
  - intros PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV HB0 HC0 HBc HCc HFB HUa _. unfold GaWA.XB. rewrite HN in *. rewrite HB in HBc. rewrite HC in HCc.
    refine (XBc_sound0 ASEGS AASAN asan_in_hull asan_hull_ok GaWA.NXF [] GASAN BCAP CCAP fx_ok SHC KCAP AINVH HP
              asan_G_ro_img2 asan_G_img_al asan_G_img_shlo nil_SWIN_img asan_segs_out asan_A_img_hi asan_A_img_lo asan_segs_wx
              PERMf TOPf FS0 HID HIDF M0 B0 C0 HB0 HC0 HBc HCc FTOPf HFB UINV HUa RZ RZ_silent1 CT2_resize _).
    intros id c' H. exact (CT2_resize_sound RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all id c' H).
  - intros i T k Hn. destruct (HCUTS i T k Hn) as (sh' & H1 & H2 & HS' & H3 & H4). exists sh'. split; [exact H1|]. split; [exact H2|].
    right. exists HS'. split; [exact H3|]. rewrite HN. exact H4.
Qed.
(* [comment removed for export] *)
Lemma xL1 : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (GaWA.ceL1 cfg).
Proof.
  refine (callee_gen_cut (GaWA.ceL1 cfg) (XCUTS cfg INVm JS1m elem) (XPLAN_L1 cfg JS0m) _ eq_refl eq_refl eq_refl gplan_XL1 hs1 _ cert_L1X).
  intros i T k H. destruct i as [|i]; [|destruct i; discriminate H]. injection H as <- <-.
  exists (SHole 1). split; [exact gplan_XC|]. split; [reflexivity|]. exact cert_CX.
Qed.

Theorem write_array_u8_asan_callee_S : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (GaWA.ce cfg MS).
Proof.
  refine (callee_gen_cutsh (GaWA.ce cfg MS) (XCUTS cfg INVm JS1m elem) (XPLAN_S cfg JS0m INVm JS1m elem) _ eq_refl eq_refl eq_refl gplan_XS hs0 _ cert_SX).
  intros i T k H. destruct i as [|i]; [|destruct i; discriminate H]. injection H as <- <-.
  exists (SHole 1). split; [exact gplan_XC|]. split; [reflexivity|].
  exists (HScut (GaWA.ceL1 cfg) (XCUTS cfg INVm JS1m elem) 1). split; [exact (xhs_sub cfg (XCUTS cfg INVm JS1m elem) eq_refl) | exact cert_CX].
Qed.
Theorem write_array_u8_asan_callee_L1 : callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH (GaWA.ceL1 cfg).
Proof. exact xL1. Qed.
End Contract.
