Import ListNotations. Import AX2. Import AP. Import GPS.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Section Contract.
Context {RC : run_ceil}.
Variable RZ : GPS.rz_t.
Hypothesis RZ_silent1 : GPS.RZ_SILENT1 ASEGS RZ.
Hypothesis RZ_exit : GPS.RZ_EXIT ASEGS RZ.
Hypothesis RZ_conseq : GPS.RZ_CONSEQ RZ.
Variable SHC : list (Z * Z).
Variable KCAP : Z.
Variable AINVH : list (Z * Z) -> list (Z * Z) -> Z -> Z -> Z -> (word -> option byte) -> Model -> Prop.
Hypothesis HP : hprops [] GASAN SHC AINVH.
Hypothesis GC_all : forall IT NXF bc cc PERMf TOPf HID HIDF M0 B0 C0 FTOPf FS0 UINV,
  itab_sound ASEGS IT -> 0 <= B0 -> 0 <= C0 -> B0 + bc <= GBUDGET -> C0 + cc <= GCOUNT -> Z.of_nat (length HIDF) + FTOPf <= FMIN ->
  (forall E E', env_agree NXF E E' -> UINV E -> UINV E') ->
  gcontracts ASEGS IT AASAN NXF PERMf TOPf FS0 SHC (VSHf HID HIDF) (AINV_f [] GASAN AINVH PERMf TOPf HID HIDF M0 B0 C0) KCAP FTOPf fx_ok UINV RZ GASAN bc cc.
(* [comment removed for export] *)
Let CERTS_L : forall i, cert_stmt ML i := GaB2Jcerts.certs_ML.
Let TOP_L : top_stmt ML := GaB2Jcerts.top_ML.
Let CERTS_S : forall i, GaB2Jcerts.lidx i = false -> cert_stmt MS i := GaB2Jcerts.certs_MSx.   (* [comment removed for export] *)
Let TOP_S : top_stmt MS := GaB2Jcerts.top_MS.

Notation CC := (callee_contract ASEGS [] GASAN fx_ok RZ SHC KCAP AINVH).
Lemma AA_L1 : forall k, (k < 10)%nat -> CC (GaAA.ceL1 (AAcfg k)).
Proof.
  intros k Hk. do 10 (destruct k as [|k]; [first
    [ exact (GaAAi8C.write_aligned_array_i8_asan_callee_L1 RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)
    | exact (GaAAi16C.write_aligned_array_i16_asan_callee_L1 RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)
    | exact (GaAAi32C.write_aligned_array_i32_asan_callee_L1 RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)
    | exact (GaAAi64C.write_aligned_array_i64_asan_callee_L1 RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)
    | exact (GaAAu8C.write_aligned_array_u8_asan_callee_L1 RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)
    | exact (GaAAu16C.write_aligned_array_u16_asan_callee_L1 RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)
    | exact (GaAAu32C.write_aligned_array_u32_asan_callee_L1 RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)
    | exact (GaAAu64C.write_aligned_array_u64_asan_callee_L1 RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)
    | exact (GaAAf32C.write_aligned_array_f32_asan_callee_L1 RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)
    | exact (GaAAf64C.write_aligned_array_f64_asan_callee_L1 RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all) ]|]).
  lia.
Qed.
