    | exact (GaAAi32C.write_aligned_array_i32_asan_callee_S RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)
    | exact (GaAAi64C.write_aligned_array_i64_asan_callee_S RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)
    | exact (GaAAu8C.write_aligned_array_u8_asan_callee_S RZ RZ_silent1 RZ_exit RZ_conseq SHC KCAP AINVH HP GC_all)
